INTRO = 'After late-night game rehearsals, writer Ji-yeon ruthlessly empties Seung-chan\'s rookie backpack and fills it with sugar snacks, instant coffee, and fish sauce, before Seung-chan buys emergency medicine for Ye-jin. Listen for "baenang", a travel backpack.'
STORY = [('seungchan', '생명은 게임이니까 미리 시뮬레이션을 하는 거죠.', 'Since games are the lifeblood of the show, we run simulations in advance.', [(737, '생명은 게임이니까'), (738, '시뮬레이션을 하는 거죠')], ''), ('seungchan', '너무 쉬워도 안 되고 너무 어려워도 안 되니까 조절이 피디의 능력인 거죠.', "It cannot be too easy or too hard, so adjusting the level is a producer's skill.", [(744, '너무 쉬워도 안 되고 너무 어려워도 안 되니까'), (746, '능력인 거죠')], ''), ('writer', '촬영은 전쟁터로 간다는 생각으로 나가야 돼요. 배낭에 쓸데없는 게 많네요.', 'You must go to a shoot as if heading to a battlefield. There is a lot of useless stuff in your backpack.', [(764, '전쟁터로 간다'), (767, '쓸데없는 게 상당히 보이네요')], ''), ('writer', '일단 치약, 칫솔 빼요. 밥도 못 먹는데 이 닦을 시간 없어요.', 'First, take out the toothpaste and toothbrush. We barely eat, so there is no time to brush teeth.', [(769, '일단 치약, 칫솔 빼요'), (770, '밥도 못 먹는데 이 닦을 시간 없어요')], ''), ('writer', '노트북? 헤드폰? 다 필요 없어요. 차에선 무조건 잘 거예요.', 'A laptop? Headphones? You need none of those. You will sleep nonstop in the van.', [(773, '노트북'), (775, '다 필요 없어요'), (776, '헤드폰'), (779, '차에선 무조건 잘 거예요')], ''), ('writer', '초콜릿, 양갱, 사탕 적으세요. 새벽 되면 당 떨어져요.', "Write down chocolate, sweet bean jelly, and candy. By dawn everyone's blood sugar drops.", [(783, '적으세요'), (784, '초콜릿, 양갱, 사탕'), (785, '새벽 되면 당 떨어져요')], ''), ('writer', '컵라면이랑 스케치북, 매직, 까나리 액젓도 꼭 챙기세요.', 'Make sure to pack cup noodles, a sketchbook, markers, and sand-lance fish sauce too.', [(787, '그리고 컵라면'), (790, '스케치북, 매직'), (792, '이거 꼭 챙기세요')], ''), ('writer', '믹스커피도요. 준모는 새벽에 그거 안 먹으면 횡설수설해요.', "And instant coffee mix. If Joon-mo doesn't drink it at dawn, he rambles incoherently.", [(794, '믹스커피'), (796, '새벽에 정신 나가서 횡설수설해')], ''), ('yejin', '너 비상약 챙겼니? 준모는 챙겨 줘야 먹는 애니까 잘 챙겨 줘.', 'Did you pack emergency medicine? Joon-mo only takes medicine if someone hands it to him, so look after him.', [(797, '챙겨줘야 먹는 애니까 네가 잘 챙겨주고'), (800, '너 비상약 챙겼니')], ''), ('seungchan', '준모 선배님은 선배님처럼 좋은 여자인 친구가 있으셔서 좋겠습니다.', 'Senior Joon-mo must be happy having such a good female friend like you.', [(803, '선배님처럼 좋은 여자친구가 있으셔서'), (804, '여자인 친구')], ''), ('yejin', '너 나 기분 좋게 해서 결제 받으려고 이러는 거잖아. 나 이만 원밖에 없다.', "You are just flattering me to collect today's installment, right? I only have twenty thousand won today.", [(807, '너 나 기분 좋게 해서'), (808, '밖에 없다 오늘')], ''), ('seungchan', '그것 때문이 아니라 정말 부러워서요.', 'It is not because of that, I truly envy him.', [(810, '정말 좋을 것 같아서요'), (811, '부러워서')], '')]
OPENER = "Now let's go through it line by line with the English translation."
WALK = [(0, None, "'Since games are the lifeblood of the show, we run simulations in advance.'"), (1, None, "'It cannot be too easy or too hard, so adjusting the level is a producer's skill.'"), (2, None, "'You must go to a shoot as if heading to a battlefield. There is a lot of useless stuff in your backpack.'"), (3, None, "'First, take out the toothpaste and toothbrush. We barely eat, so there is no time to brush teeth.'"), (4, None, "'A laptop? Headphones? You need none of those. You will sleep nonstop in the van.'"), (5, None, "'Write down chocolate, sweet bean jelly, and candy. By dawn everyone's blood sugar drops.'"), (6, None, "'Make sure to pack cup noodles, a sketchbook, markers, and sand-lance fish sauce too.'"), (7, None, "'And instant coffee mix. If Joon-mo doesn't drink it at dawn, he rambles incoherently.'"), (8, None, "'Did you pack emergency medicine? Joon-mo only takes medicine if someone hands it to him, so look after him.'"), (9, None, "'Senior Joon-mo must be happy having such a good female friend like you.'"), (10, None, "'You are just flattering me to collect today's installment, right? I only have twenty thousand won today.'"), (11, None, "'It is not because of that, I truly envy him.'")]
